CREATE OR REPLACE FUNCTION ECAMS.SECUCHK
(USERID VARCHAR2,SYSCD varchar2,JOBCD VARCHAR2)
return VARCHAR2
IS
    CNT     INTEGER;
BEGIN
    SELECT COUNT(*)
      INTO CNT
      FROM CMM0044
     WHERE CM_USERID=USERID
       AND CM_SYSCD=SYSCD
       AND CM_JOBCD=JOBCD
       AND CM_CLOSEDT IS NULL;
    IF CNT = 0 THEN RETURN 'NO';
    ELSE RETURN 'OK';
    END IF;
END ;